contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint putAmount, uint collectAmount) public payable {
        // Need enough Ether to deposit.
        require(address(this).balance >= putAmount);

        // Deposit so that the caller has a balance and an unlock time that is already in the past.
        c.Put{value: putAmount}(0);

        // Pre-state read through public getter.
        (, uint balBefore) = c.Acc(address(this));

        // The test contract holds the Ether that c will send during Collect.
        // Ensure we actually ask for a valid successful Collect: collectAmount must be
        // at least MinSum, at most the recorded balance, and the unlock time must have passed.
        require(collectAmount >= c.MinSum() && collectAmount <= balBefore);

        uint contractBalBefore = address(c).balance;

        // Perform the collect; this is the deciding call.
        c.Collect(collectAmount);

        // Post-state read through public getter.
        (, uint balAfter) = c.Acc(address(this));
        uint contractBalAfter = address(c).balance;

        // General rule: after a successful Collect, the caller's recorded balance and
        // the contract's Ether balance both drop by exactly the withdrawn amount.
        assert(balAfter == balBefore - collectAmount && contractBalAfter == contractBalBefore - collectAmount);
    }

    receive() external payable {}
}

